// Automatic Search Index Generator
function generateSearchIndex(navTree) {
  const index = [];

  function traverse(item, groupHeading, parentBreadcrumbs = []) {
    const breadcrumb = [...parentBreadcrumbs, item.label];
    const itemPath = item.to || "";
    
    // Check if we have rich metadata for this exact URL
    const meta = sectionMetadataMap[itemPath];

    if (item.to) {
      let pageName = meta?.pageName;
      let sectionName = meta?.sectionName;
      let matchedHeading = meta?.matchedHeading || item.label;

      if (!pageName) {
        pageName = breadcrumb[0] || item.label;
        sectionName = breadcrumb.length > 2 ? breadcrumb[1] : (breadcrumb.length === 2 ? breadcrumb[1] : "");
      }

      index.push({
        to: item.to,
        group: groupHeading,
        pageName: pageName,
        sectionName: sectionName,
        matchedHeading: matchedHeading,
        breadcrumb: breadcrumb,
        desc: meta?.desc || `Documentation for ${item.label} in ${groupHeading}.`,
        keywords: meta?.keywords || `${item.label} ${groupHeading} ${breadcrumb.join(" ")}`.toLowerCase(),
      });
    }

    if (item.children && Array.isArray(item.children)) {
      item.children.forEach((child) => traverse(child, groupHeading, breadcrumb));
    }
  }

  navTree.forEach((group) => {
    group.items.forEach((item) => traverse(item, group.heading, []));
  });

  return index;
}

export const searchIndex = generateSearchIndex(nav);
